//! Save protection and graph limits for linked sources. All files are generated by these
//! tests in their own temporary directories; media pixels are authored here.

#![cfg(not(target_arch = "wasm32"))]

use std::path::{Path, PathBuf};
use std::sync::Arc;

use effectcraft_color::Label;
use effectcraft_project::{Comp, Footage, FootageKind, ItemId, ItemKind, LayerSource, Project, Proxy};
use effectcraft_time::{FrameRate, Tick};
use serde_json::json;

use crate::Session;

struct Fixture {
    directory: tempfile::TempDir,
    source: PathBuf,
    media: Vec<PathBuf>,
    own: PathBuf,
    destination: Session,
}

fn comp(session: &mut Session, name: &str) -> ItemId {
    let result = session.execute("comp.new", json!({"name":name,"width":4,"height":4,"duration":1})).unwrap();
    ItemId(result["comp"].as_u64().unwrap())
}

fn save(session: &mut Session, path: &Path) {
    session.execute("file.saveAs", json!({"path":path.to_string_lossy()})).unwrap();
}

fn fixture(source_name: &str) -> Fixture {
    let parent = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/test-out/linked-hardening");
    std::fs::create_dir_all(&parent).unwrap();
    let directory = tempfile::Builder::new().prefix("save-").tempdir_in(parent).unwrap();
    let source_path = directory.path().join(source_name);
    let own = directory.path().join("Main.ecproj");
    let media: Vec<_> = ["plate.png", "frame1.png", "frame2.png", "proxy.png"].into_iter().map(|name| directory.path().join(name)).collect();
    for path in &media {
        image::RgbaImage::from_pixel(4, 4, image::Rgba([32, 96, 160, 255])).save(path).unwrap();
    }
    let footage = |path: &str| Footage { path: path.into(), kind: FootageKind::Still, width: 4, height: 4, ..Footage::default() };
    let mut source = Session::default();
    let opening = comp(&mut source, "Opening");
    let project = Arc::make_mut(&mut source.project);
    project.add_item("Plate", Label::Aqua, None, ItemKind::Footage(footage("plate.png")));
    project.add_item(
        "Sequence",
        Label::Aqua,
        None,
        ItemKind::Footage(Footage { kind: FootageKind::Sequence, sequence: vec!["frame1.png".into(), "frame2.png".into()], ..footage("frame1.png") }),
    );
    project.items.get_mut(&opening).unwrap().proxy = Some(Box::new(Proxy { footage: footage("proxy.png"), enabled: false }));
    save(&mut source, &source_path);

    let mut destination = Session::default();
    comp(&mut destination, "Main");
    destination.execute("file.linkComposition", json!({"path":source_path.to_string_lossy(),"comp":"Opening"})).unwrap();
    save(&mut destination, &own);
    comp(&mut destination, "Unsaved local edit");
    Fixture { directory, source: source_path, media, own, destination }
}

fn refused_without_changing_session(session: &mut Session, command: &str, params: serde_json::Value) {
    let project = session.project.clone();
    let path = session.path.clone();
    let history = session.history.undo.len();
    let dirty = session.is_dirty();
    let error = session.execute(command, params).unwrap_err().to_string();
    assert!(error.contains("linked composition source or dependency"), "{error}");
    assert!(Arc::ptr_eq(&session.project, &project), "a refused save must not publish the staged project");
    assert_eq!(session.path, path);
    assert_eq!(session.history.undo.len(), history);
    assert_eq!(session.is_dirty(), dirty);
}

#[test]
fn saving_cannot_replace_a_linked_source_or_hidden_media_but_can_save_the_destination() {
    let mut f = fixture("Source.ecproj");
    let original = std::fs::read(&f.own).unwrap();
    for path in std::iter::once(&f.source).chain(&f.media) {
        let bytes = std::fs::read(path).unwrap();
        for command in ["file.save", "file.saveAs"] {
            refused_without_changing_session(&mut f.destination, command, json!({"path":path.to_string_lossy()}));
            assert_eq!(std::fs::read(path).unwrap(), bytes);
        }
    }
    assert_eq!(std::fs::read(&f.own).unwrap(), original);
    f.destination.execute("file.save", json!({})).unwrap();
    assert_ne!(std::fs::read(&f.own).unwrap(), original, "the destination's normal Save must remain usable");
    assert!(!f.destination.is_dirty());
}

#[test]
fn linked_save_protection_recognizes_native_aliases_and_normalized_names() {
    let mut f = fixture("Source.ecproj");
    for (index, original) in [&f.source, &f.media[0]].into_iter().enumerate() {
        let alias = f.directory.path().join(format!("alias{index}.ecproj"));
        std::fs::hard_link(original, &alias).unwrap();
        let bytes = std::fs::read(original).unwrap();
        refused_without_changing_session(&mut f.destination, "file.saveAs", json!({"path":alias.to_string_lossy()}));
        assert_eq!(std::fs::read(original).unwrap(), bytes);
        assert_eq!(std::fs::read(alias).unwrap(), bytes);
    }
    let folder = f.directory.path().join("folder");
    std::fs::create_dir(&folder).unwrap();
    let normalized_alias = folder.join("..").join("Source.ecproj");
    refused_without_changing_session(&mut f.destination, "file.saveAs", json!({"path":normalized_alias.to_string_lossy()}));
}

#[test]
fn missing_media_paths_remain_owned_by_the_loaded_linked_source() {
    let mut f = fixture("Source.ecproj");
    for media in &f.media {
        std::fs::remove_file(media).unwrap();
        refused_without_changing_session(&mut f.destination, "file.saveAs", json!({"path":media.to_string_lossy()}));
        assert!(!media.exists(), "a save cannot recreate missing source media as a project file");
    }
}

#[test]
fn an_offline_link_still_protects_its_source_project_path() {
    let mut f = fixture("Source.ecproj");
    std::fs::remove_file(&f.source).unwrap();
    let result = f.destination.execute("project.refreshLinkedCompositions", json!({})).unwrap();
    assert!(!result["errors"].as_array().unwrap().is_empty());
    refused_without_changing_session(&mut f.destination, "file.saveAs", json!({"path":f.source.to_string_lossy()}));
    assert!(!f.source.exists());
}

#[test]
fn failed_refresh_keeps_known_media_owned_without_rendering_the_old_snapshot() {
    let mut f = fixture("Source.ecproj");
    let saved_source = std::fs::read(&f.source).unwrap();
    std::fs::remove_file(&f.source).unwrap();
    for corrupt in [false, true] {
        if corrupt {
            std::fs::write(&f.source, b"incomplete source save").unwrap();
        }
        // Repeated failures must not erase the retained ownership either.
        for _ in 0..2 {
            f.destination.execute("project.refreshLinkedCompositions", json!({})).unwrap();
            let link = f
                .destination
                .project
                .items
                .values()
                .find_map(|item| match &item.kind {
                    ItemKind::Footage(footage) if footage.kind == FootageKind::LinkedComposition => footage.linked_comp.as_ref(),
                    _ => None,
                })
                .unwrap();
            assert!(link.resolved.is_none() && link.resolved_comp.is_none() && link.error.is_some(), "an offline source must not render stale pixels");
            assert!(link.last_known_source.is_some());
            for path in &f.media {
                let original = std::fs::read(path).unwrap();
                refused_without_changing_session(&mut f.destination, "file.saveAs", json!({"path":path.to_string_lossy()}));
                assert_eq!(std::fs::read(path).unwrap(), original);
            }
        }
    }
    let alias = f.directory.path().join("offline-media-alias.ecproj");
    std::fs::hard_link(&f.media[0], &alias).unwrap();
    refused_without_changing_session(&mut f.destination, "file.saveAs", json!({"path":alias.to_string_lossy()}));
    for command in ["edit.undo", "edit.redo"] {
        f.destination.execute(command, json!({})).unwrap();
        for path in &f.media {
            refused_without_changing_session(&mut f.destination, "file.saveAs", json!({"path":path.to_string_lossy()}));
        }
    }
    let serialized = f.destination.project.to_file_json().unwrap();
    assert!(!serialized.contains("last_known_source"), "guard ownership must not embed source contents in the project file");
    std::fs::write(&f.source, saved_source).unwrap();
    f.destination.execute("project.refreshLinkedCompositions", json!({})).unwrap();
    let link = f
        .destination
        .project
        .items
        .values()
        .find_map(|item| match &item.kind {
            ItemKind::Footage(footage) if footage.kind == FootageKind::LinkedComposition => footage.linked_comp.as_ref(),
            _ => None,
        })
        .unwrap();
    assert!(
        link.resolved.is_some() && link.last_known_source.is_none() && link.error.is_none(),
        "recovery replaces guard-only ownership with the current source"
    );
}

#[test]
fn link_admission_requires_unique_stable_ids_for_all_source_items() {
    let mut f = fixture("Source.ecproj");
    let saved: serde_json::Value = serde_json::from_slice(&std::fs::read(&f.source).unwrap()).unwrap();
    for duplicated in [false, true] {
        let mut malformed = saved.clone();
        let items = malformed["items"].as_object_mut().unwrap();
        let comp_id = items.values().find(|item| item["kind"]["type"] == "Comp").unwrap()["stable_id"].clone();
        let footage = items.values_mut().find(|item| item["kind"]["type"] == "Footage").unwrap();
        if duplicated {
            footage["stable_id"] = comp_id;
        } else {
            footage.as_object_mut().unwrap().remove("stable_id");
        }
        std::fs::write(&f.source, malformed.to_string()).unwrap();
        let before = f.destination.project.clone();
        let error = f.destination.execute("file.linkableCompositions", json!({"path":f.source.to_string_lossy()})).unwrap_err().to_string();
        assert!(error.contains("item identities"), "source admission must match worker identity validation: {error}");
        assert_eq!(*f.destination.project, *before, "listing an invalid source cannot change the destination");
    }
}

#[test]
fn increment_save_cannot_recreate_a_missing_linked_source() {
    let mut f = fixture("Main 2.ecproj");
    let original = std::fs::read(&f.own).unwrap();
    std::fs::remove_file(&f.source).unwrap();
    refused_without_changing_session(&mut f.destination, "file.incrementAndSave", json!({}));
    assert!(!f.source.exists());
    assert_eq!(std::fs::read(&f.own).unwrap(), original);
}

#[test]
fn save_as_and_increment_preserve_identity_while_new_project_starts_another_identity() {
    let mut f = fixture("Source.ecproj");
    let identity = f.destination.project.project_id.clone();
    let items: Vec<_> = f.destination.project.items.values().map(|item| (item.id, item.stable_id.clone())).collect();
    let relocated = f.directory.path().join("Relocated.ecproj");
    save(&mut f.destination, &relocated);
    f.destination.execute("file.incrementAndSave", json!({})).unwrap();
    assert_eq!(f.destination.project.project_id, identity);
    assert_eq!(f.destination.project.items.values().map(|item| (item.id, item.stable_id.clone())).collect::<Vec<_>>(), items);
    let saved = Project::from_json(&std::fs::read_to_string(f.destination.path.as_ref().unwrap()).unwrap()).unwrap();
    assert_eq!(saved.project_id, identity);
    assert_eq!(saved.items.values().map(|item| (item.id, item.stable_id.clone())).collect::<Vec<_>>(), items);
    f.destination.execute("file.newProject", json!({})).unwrap();
    assert_ne!(f.destination.project.project_id, identity);
}

fn graph_comp(project: &mut Project) -> ItemId {
    project.add_item("Composition", Label::Sandstone, None, ItemKind::Comp(Arc::new(Comp::new(4, 4, FrameRate::FPS_30, Tick::from_seconds_f64(1.0)))))
}

fn nest(project: &mut Project, parent: ItemId, child: ItemId) {
    let comp = project.comp(parent).unwrap().clone();
    let layer = effectcraft_project::build::layer(project, &comp, "Nested", LayerSource::Comp { item: child }, (4, 4), Some(comp.duration));
    project.comp_mut(parent).unwrap().layers.push(layer);
}

fn chain(project: &mut Project, length: usize) -> Vec<ItemId> {
    let items: Vec<_> = (0..length).map(|_| graph_comp(project)).collect();
    for pair in items.windows(2) {
        nest(project, pair[0], pair[1]);
    }
    items
}

#[test]
fn composition_depth_includes_shared_tails_on_every_route() {
    let mut project = Project::default();
    let shared = chain(&mut project, 7);
    let short = chain(&mut project, 2);
    nest(&mut project, short[1], shared[0]);
    let shallow = graph_comp(&mut project);
    nest(&mut project, shallow, short[0]);
    nest(&mut project, shallow, shared[0]);
    assert!(crate::linked_compositions::validate_comp(&project, shallow).is_ok());

    let long = chain(&mut project, 7);
    nest(&mut project, long[6], shared[0]);
    for children in [[long[0], shared[0]], [shared[0], long[0]]] {
        let deep = graph_comp(&mut project);
        for child in children {
            nest(&mut project, deep, child);
        }
        let error = crate::linked_compositions::validate_comp(&project, deep).unwrap_err();
        assert!(error.contains("depth"), "a shared dependency cannot conceal an over-deep path: {error}");
    }
}

#[test]
fn linked_composition_validation_refuses_cycles_and_missing_compositions() {
    let mut project = Project::default();
    let items = chain(&mut project, 3);
    nest(&mut project, items[2], items[0]);
    let error = crate::linked_compositions::validate_comp(&project, items[0]).unwrap_err();
    assert!(error.contains("cycle"), "{error}");
    project.comp_mut(items[2]).unwrap().layers.clear();
    project.items.remove(&items[2]);
    let error = crate::linked_compositions::validate_comp(&project, items[0]).unwrap_err();
    assert!(error.contains("Missing composition"), "{error}");
}
